#include <bits/stdc++.h>
using namespace std;const int N=100000;int p[N],n;bool v[N+5];long long P,M;long long z(long long x){x%=M;return x<0?x+M:x;}long long s(long long x){long long a=x,b=x+1;if(a&1)b/=2;else a/=2;return a%M*(b%M)%M;}long long E(int q,int a,int b,int c){long long x=0,y=0,u=0,w=0,t=q,L=max(a,max(b,c));while(t<=L){long long A=t%M*s(a/t)%M,B=t%M*s(b/t)%M,C=t%M*s(c/t)%M;x=(x+A)%M;y=(y+B)%M;u=(u+A*B)%M;w=(w+A*C)%M;if(t>L/q)break;t*=q;}return z(s(b)*s(c)%M*x+s(a)*s(c)%M*y-s(c)*u-s(b)*w);}long long k(long long a,long long b){long long r=1;for(;b;b>>=1,a=a*a%P)if(b&1)r=r*a%P;return r;}int main(){ios::sync_with_stdio(0);cin.tie(0);for(int i=2;i<=N;i++){if(!v[i])p[n++]=i;for(int j=0;j<n&&i*p[j]<=N;j++){v[i*p[j]]=1;if(i%p[j]==0)break;}}int T;cin>>T>>P;M=P-1;while(T--){int a,b,c;cin>>a>>b>>c;long long r=1;for(int i=0;i<n&&p[i]<=max(a,b);i++)r=r*k(p[i],E(p[i],a,b,c))%P;cout<<"0 "<<r<<" 0\n";}}
